(() => {
  // Windows 52px 顶栏(与 macOS 同款): 磨砂玻璃悬浮栏 + 吉祥物图标 + 服务状态胶囊
  // + 主题下拉(5 内置主题/工坊/统计) + 模型设置 + 更新 + 最小化/最大化/隐藏。
  // 整条可拖拽窗口(-webkit-app-region: drag), 按钮区域 no-drag;
  // 页面顶部 _frame 预留 52px, 内容从顶栏之下开始。
  if (window.__dsmWindowsChrome) return;
  window.__dsmWindowsChrome = true;

  const DEFAULT_MASCOT = 'data:image/png;base64,';
  const STATUS_LABELS = { online: '已连接', starting: '正在启动', offline: '服务异常' };
  const FALLBACK_THEMES = [
    { id: 'official', label: '官方样式' },
    { id: 'cute', label: '正太主题' },
    { id: 'aurora', label: '暗夜极光' },
    { id: 'paper', label: '奶油纸感' },
    { id: 'deepsea', label: '深海鲸语' }
  ];

  let mascotURL = (typeof window.__dsmMascotURL === 'string' && window.__dsmMascotURL)
    ? window.__dsmMascotURL
    : DEFAULT_MASCOT;
  let themeList = FALLBACK_THEMES.slice();
  let currentThemeId = 'cute';
  let topState = 'starting';

  const style = document.createElement('style');
  style.textContent = `
    :root { --dsm-chrome-h: 52px; }

    /* 页面顶部留白: 内容从 52px 顶栏之下开始 */
    [class$="_frame"] { box-sizing: border-box; padding-top: var(--dsm-chrome-h) !important; }
    html [class$="_frame"] { padding-top: var(--dsm-chrome-h) !important; }

    .dsm-windows-titlebar {
      position: fixed; inset: 0 0 auto 0; height: var(--dsm-chrome-h); z-index: 2147483646;
      display: flex; align-items: center; justify-content: space-between;
      padding: 0 0 0 14px;
      pointer-events: auto; user-select: none;
      background: color-mix(in srgb, var(--dsw-alias-bg-base, #ffffff) 64%, transparent);
      -webkit-backdrop-filter: blur(24px) saturate(175%);
      backdrop-filter: blur(24px) saturate(175%);
      border-bottom: 1px solid color-mix(in srgb, var(--dsw-alias-label-primary, #101010) 9%, transparent);
      -webkit-app-region: drag;
    }
    .dsm-windows-titlebar::after {
      content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
      background: linear-gradient(90deg,
        transparent 3%,
        color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 30%, transparent) 50%,
        transparent 97%);
      opacity: .85; pointer-events: none;
    }
    .dsm-windows-left, .dsm-windows-right { display: flex; align-items: center; gap: 10px; }
    .dsm-windows-right { gap: 8px; padding-right: 4px; }

    /* 吉祥物图标(可经主题工坊自定义) */
    .dsm-avatar {
      display: inline-block; flex: 0 0 auto;
      background-size: cover; background-position: center; background-repeat: no-repeat;
    }
    .dsm-bar-mascot {
      -webkit-app-region: no-drag;
      width: 26px; height: 26px; border-radius: 9px; cursor: default;
      box-shadow:
        inset 0 0 0 1px color-mix(in srgb, var(--dsw-alias-label-primary, #000000) 14%, transparent),
        0 2px 8px rgba(20, 18, 30, .10);
    }

    /* 服务状态胶囊(接管 interactions.js 的旧状态灯) */
    #dsmTopStatus {
      -webkit-app-region: no-drag;
      display: inline-flex; align-items: center; gap: 7px;
      height: 28px; padding: 0 12px; border-radius: 999px;
      border: 1px solid color-mix(in srgb, var(--dsw-alias-label-primary, #101010) 13%, transparent);
      background: color-mix(in srgb, var(--dsw-alias-bg-layer-2, #f4f4f6) 80%, transparent);
      -webkit-backdrop-filter: blur(12px) saturate(150%);
      backdrop-filter: blur(12px) saturate(150%);
      color: var(--dsw-alias-label-primary, #101010);
      font: 600 12px/1 system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
      letter-spacing: .02em; cursor: default;
      box-shadow: 0 4px 14px rgba(24, 20, 32, .10);
      transition: background-color .25s ease, border-color .25s ease, box-shadow .25s ease;
    }
    #dsmTopStatus:not([data-state="online"]) { cursor: pointer; }
    #dsmTopStatus:not([data-state="online"]):hover {
      border-color: color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 45%, transparent);
      box-shadow: 0 5px 16px rgba(24, 20, 32, .14);
    }
    .dsm-top-dot {
      width: 8px; height: 8px; border-radius: 50%;
      background: #f5b942;
      box-shadow: 0 0 0 3px color-mix(in srgb, #f5b942 22%, transparent);
      transition: background-color .3s ease, box-shadow .3s ease;
    }
    #dsmTopStatus[data-state="online"] .dsm-top-dot {
      background: #34c77b; box-shadow: 0 0 0 3px rgba(52, 199, 123, .20);
    }
    #dsmTopStatus[data-state="offline"] .dsm-top-dot {
      background: #f0564a; box-shadow: 0 0 0 3px rgba(240, 86, 74, .22);
      animation: dsmTopPulse 1.6s ease-in-out infinite;
    }
    @keyframes dsmTopPulse { 50% { opacity: .4; } }
    @media (prefers-reduced-motion: reduce) {
      #dsmTopStatus[data-state="offline"] .dsm-top-dot { animation: none; }
    }
    .dsm-service-pill { display: none !important; }

    /* 胶囊/功能按钮 */
    .dsm-pill {
      -webkit-app-region: no-drag;
      height: 28px; padding: 0 11px; border-radius: 999px;
      border: 1px solid color-mix(in srgb, var(--dsw-alias-label-primary, #101010) 13%, transparent);
      background: color-mix(in srgb, var(--dsw-alias-bg-layer-2, #f4f4f6) 80%, transparent);
      -webkit-backdrop-filter: blur(12px) saturate(150%);
      backdrop-filter: blur(12px) saturate(150%);
      color: var(--dsw-alias-label-primary, #101010);
      font: 600 12px/1 system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
      letter-spacing: .02em; cursor: pointer;
      box-shadow: 0 4px 14px rgba(24, 20, 32, .10);
      transition: background-color .25s ease, border-color .25s ease;
    }
    .dsm-pill:hover {
      border-color: color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 45%, transparent);
      background: color-mix(in srgb, var(--dsw-alias-bg-layer-2, #f4f4f6) 92%, transparent);
    }
    .dsm-update-pill[data-state='checking'] { color: var(--dsw-alias-label-primary, #101010); opacity: .75; }
    .dsm-update-pill[data-state='downloading'] { color: #b78900; }
    .dsm-update-pill[data-state='ready'] {
      color: var(--dsw-alias-brand-primary, #1d9f8a);
      animation: dsmUpdatePulse 1s ease-in-out infinite alternate;
    }
    .dsm-update-pill[data-state='error'] { color: #c0392b; }
    @keyframes dsmUpdatePulse { to { box-shadow: 0 0 15px color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 45%, transparent); } }

    /* 窗口控制按钮(最小化/最大化/隐藏) */
    .dsm-windows-controls { display: flex; height: var(--dsm-chrome-h); -webkit-app-region: no-drag; }
    .dsm-windows-control {
      width: 46px; height: var(--dsm-chrome-h); border: 0; padding: 0; box-shadow: none;
      display: grid; place-items: center;
      color: var(--dsw-alias-label-primary, #101010); background: transparent;
      font: 500 15px/1 system-ui; cursor: pointer;
      transition: background-color .15s ease;
    }
    .dsm-windows-control:hover { background: color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 16%, transparent); }
    .dsm-windows-control[data-action='close']:hover { background: #e85b4f; color: #fff; }

    /* 主题下拉菜单 */
    .dsm-theme-menu {
      position: fixed; z-index: 2147483647; min-width: 176px; padding: 6px;
      border-radius: 12px;
      border: 1px solid color-mix(in srgb, var(--dsw-alias-label-primary, #101010) 12%, transparent);
      background: color-mix(in srgb, var(--dsw-alias-bg-base, #ffffff) 88%, transparent);
      -webkit-backdrop-filter: blur(24px) saturate(175%);
      backdrop-filter: blur(24px) saturate(175%);
      box-shadow: 0 18px 44px rgba(10, 12, 24, .22);
      -webkit-app-region: no-drag;
    }
    .dsm-theme-item {
      width: 100%; display: flex; align-items: center; justify-content: space-between; gap: 10px;
      padding: 8px 10px; border: 0; border-radius: 8px; background: transparent;
      color: var(--dsw-alias-label-primary, #101010);
      font: 600 12px/1.2 system-ui, "Microsoft YaHei", "PingFang SC", sans-serif;
      text-align: left; cursor: pointer;
    }
    .dsm-theme-item:hover { background: color-mix(in srgb, var(--dsw-alias-brand-primary, #4c8dff) 14%, transparent); }
    .dsm-theme-item.is-active { color: var(--dsw-alias-brand-primary, #4c8dff); }
    .dsm-theme-check { font-size: 11px; }
    .dsm-theme-sep { height: 1px; margin: 6px 4px; background: color-mix(in srgb, var(--dsw-alias-label-primary, #101010) 12%, transparent); }

    /* 模型名称以大写显示(用户偏好) */
    button[class$="_trigger"] span[class$="_triggerLabel"] {
      text-transform: uppercase; letter-spacing: .04em; font-weight: 700;
    }

    /* ---------- 吉祥物头像(官方模式替换品牌/欢迎区形象) ---------- */
    .dsm-brand-avatar {
      width: 26px; height: 26px; border-radius: 9px;
      box-shadow:
        inset 0 0 0 1px color-mix(in srgb, var(--dsw-alias-label-primary, #000000) 14%, transparent),
        0 2px 8px rgba(20, 18, 30, .10);
    }
    .dsm-hero-avatar {
      width: 64px; height: 64px; border-radius: 22px;
      box-shadow:
        inset 0 0 0 1px color-mix(in srgb, var(--dsw-alias-label-primary, #000000) 12%, transparent),
        0 10px 26px rgba(24, 20, 36, .16);
    }
    [class*="_fishHitbox"] {
      display: inline-flex !important; align-items: center !important; justify-content: center !important;
    }
    html[data-dsm-theme="official"] .dsm-hero-avatar { animation: dsmHeroBreath 4.2s ease-in-out infinite; }
    @keyframes dsmHeroBreath { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }
    @media (prefers-reduced-motion: reduce) {
      html[data-dsm-theme="official"] .dsm-hero-avatar { animation: none; }
    }
  `;
  document.documentElement.appendChild(style);

  // ---------- 顶栏骨架 ----------
  const bar = document.createElement('div');
  bar.className = 'dsm-windows-titlebar';
  bar.innerHTML = `
    <span class="dsm-windows-left">
      <span class="dsm-avatar dsm-bar-mascot" title="应用图标"></span>
      <button type="button" id="dsmTopStatus" data-state="starting">
        <span class="dsm-top-dot"></span><span class="dsm-top-label">正在启动</span>
      </button>
    </span>
    <span class="dsm-windows-right">
      <button type="button" class="dsm-pill dsm-theme-pill" title="切换界面主题">正太主题</button>
      <button type="button" class="dsm-pill dsm-model-pill" title="选择 DeepSeek 官方或本地千问模型">模型设置</button>
      <button type="button" class="dsm-pill dsm-update-pill" data-state="idle" title="点击检查更新">检查更新</button>
      <span class="dsm-windows-controls">
        <button type="button" class="dsm-windows-control" data-action="minimize" title="最小化">—</button>
        <button type="button" class="dsm-windows-control" data-action="maximize" title="最大化">□</button>
        <button type="button" class="dsm-windows-control" data-action="close" title="隐藏窗口">×</button>
      </span>
    </span>`;
  document.body.appendChild(bar);

  const themePill = bar.querySelector('.dsm-theme-pill');
  const modelPill = bar.querySelector('.dsm-model-pill');
  const updatePill = bar.querySelector('.dsm-update-pill');
  const statusButton = bar.querySelector('#dsmTopStatus');

  // ---------- 主题下拉菜单 ----------
  const themeMenu = document.createElement('div');
  themeMenu.className = 'dsm-theme-menu';
  themeMenu.hidden = true;
  document.body.appendChild(themeMenu);

  const escapeHtml = (value) => String(value)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  const themeLabel = (id) => {
    const found = themeList.find((t) => t.id === id);
    return found ? found.label : id;
  };

  const renderThemeMenu = () => {
    themeMenu.innerHTML = '';
    for (const item of themeList) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'dsm-theme-item' + (item.id === currentThemeId ? ' is-active' : '');
      button.innerHTML = `<span>${escapeHtml(item.label)}</span>` +
        (item.id === currentThemeId ? '<span class="dsm-theme-check">✓</span>' : '');
      button.addEventListener('click', () => {
        closeThemeMenu();
        if (item.id !== currentThemeId) window.deepseekDesktop?.setTheme(item.id);
      });
      themeMenu.appendChild(button);
    }
    const sep = document.createElement('div');
    sep.className = 'dsm-theme-sep';
    themeMenu.appendChild(sep);
    const extras = [
      { label: '主题工坊…', action: () => window.deepseekDesktop?.openThemeStudio() },
      { label: '使用统计', action: () => window.deepseekDesktop?.openStats() }
    ];
    for (const extra of extras) {
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'dsm-theme-item';
      button.textContent = extra.label;
      button.addEventListener('click', () => { closeThemeMenu(); extra.action(); });
      themeMenu.appendChild(button);
    }
  };

  const openThemeMenu = () => {
    renderThemeMenu();
    const rect = themePill.getBoundingClientRect();
    themeMenu.hidden = false;
    themeMenu.style.top = `${rect.bottom + 6}px`;
    themeMenu.style.right = `${Math.max(8, window.innerWidth - rect.right)}px`;
  };
  const closeThemeMenu = () => { themeMenu.hidden = true; };
  document.addEventListener('click', (event) => {
    if (themeMenu.hidden) return;
    if (themeMenu.contains(event.target) || themePill.contains(event.target)) return;
    closeThemeMenu();
  });
  document.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') closeThemeMenu();
  });

  themePill.addEventListener('click', () => {
    if (themeMenu.hidden) openThemeMenu();
    else closeThemeMenu();
  });

  const applyThemeMode = (mode) => {
    currentThemeId = mode === 'official' ? 'official'
      : (themeList.some((t) => t.id === mode) ? mode : 'cute');
    document.documentElement.dataset.dsmTheme = currentThemeId;
    themePill.textContent = themeLabel(currentThemeId);
    themePill.title = '当前主题：' + themeLabel(currentThemeId) + '，点击切换';
    if (!themeMenu.hidden) renderThemeMenu();
    chromeRefresh();
  };
  window.__dsmWindowsThemeChanged = applyThemeMode;

  // ---------- 服务状态胶囊 ----------
  const setServiceStatus = (state) => {
    topState = STATUS_LABELS[state] ? state : 'offline';
    statusButton.dataset.state = topState;
    statusButton.querySelector('.dsm-top-label').textContent = STATUS_LABELS[topState];
    statusButton.title = topState === 'online' ? '本地服务运行正常' : '点击尝试恢复本地服务';
  };
  window.__dsmSetServiceStatus = setServiceStatus;
  statusButton.addEventListener('click', () => {
    try {
      window.webkit?.messageHandlers?.dsmService?.postMessage(topState === 'online' ? 'check' : 'recover');
    } catch (_) {}
  });

  // ---------- 吉祥物 ----------
  const applyMascot = (url) => {
    document.querySelectorAll('.dsm-bar-mascot, .dsm-avatar').forEach((el) => {
      el.style.backgroundImage = 'url("' + (url || DEFAULT_MASCOT) + '")';
    });
  };
  window.__dsmApplyMascot = (url) => {
    mascotURL = url || DEFAULT_MASCOT;
    applyMascot(mascotURL);
  };
  applyMascot(mascotURL);

  // 官方模式: 品牌行与欢迎区鲸鱼替换为吉祥物头像(cute 主题由主题 CSS 自带形象)
  const isOfficial = () => document.documentElement.dataset.dsmTheme === 'official';

  const decorateBrand = (button) => {
    if (button.dataset.dsmBrandDone) return;
    button.dataset.dsmBrandDone = '1';
    const identity = button.querySelector('[class*="_brandIdentity"]');
    const mark = button.querySelector('[class*="_brandMark"]');
    const name = button.querySelector('[class*="_brandName"]');
    if (mark) mark.style.display = 'none';
    if (name) name.style.display = 'none';
    const av = document.createElement('span');
    av.className = 'dsm-avatar dsm-brand-avatar';
    (identity || (mark && mark.parentElement) || button)
      .insertBefore(av, identity ? identity.firstChild : (mark || button.firstChild));
    av.style.backgroundImage = 'url("' + mascotURL + '")';
  };

  const decorateHero = (headline) => {
    if (headline.dataset.dsmHeroDone) return;
    const fish = headline.querySelector('svg[class*="_fish"], svg');
    if (!fish) return;
    headline.dataset.dsmHeroDone = '1';
    fish.style.display = 'none';
    const hitbox = headline.querySelector('[class*="_fishHitbox"]') || headline;
    const av = document.createElement('span');
    av.className = 'dsm-avatar dsm-hero-avatar';
    hitbox.insertBefore(av, hitbox.firstChild);
    av.style.backgroundImage = 'url("' + mascotURL + '")';
  };

  const scanChrome = (root) => {
    if (!isOfficial()) return;
    root.querySelectorAll('button[class*="_brand"]').forEach(decorateBrand);
    root.querySelectorAll('[class*="_headline"]').forEach(decorateHero);
  };
  scanChrome(document);

  let scanTimer = 0;
  const scheduleScan = () => {
    if (scanTimer) return;
    scanTimer = window.setTimeout(() => { scanTimer = 0; scanChrome(document); }, 260);
  };
  const mo = new MutationObserver((records) => {
    let hit = false;
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType !== Node.ELEMENT_NODE) continue;
        if (node.matches?.('button[class*="_brand"], [class*="_headline"]') ||
            node.querySelector?.('button[class*="_brand"], [class*="_headline"]')) { hit = true; break; }
      }
      if (hit) break;
    }
    if (hit) scheduleScan();
  });
  mo.observe(document.documentElement, { childList: true, subtree: true });

  const chromeRefresh = () => {
    document.querySelectorAll('.dsm-brand-avatar, .dsm-hero-avatar').forEach((el) => el.remove());
    document.querySelectorAll('[data-dsm-brand-done]').forEach((el) => {
      delete el.dataset.dsmBrandDone;
      const mark = el.querySelector('[class*="_brandMark"]');
      const name = el.querySelector('[class*="_brandName"]');
      if (mark) mark.style.display = '';
      if (name) name.style.display = '';
    });
    document.querySelectorAll('[data-dsm-hero-done]').forEach((el) => {
      delete el.dataset.dsmHeroDone;
      const fish = el.querySelector('svg[class*="_fish"], svg');
      if (fish) fish.style.display = '';
    });
    scanChrome(document);
  };

  // ---------- 按钮 ----------
  modelPill.addEventListener('click', () => window.deepseekDesktop?.openModelSettings());
  updatePill.addEventListener('click', () => window.deepseekDesktop?.checkForUpdates());
  bar.querySelectorAll('.dsm-windows-control').forEach((button) => {
    button.addEventListener('click', () => window.deepseekDesktop?.windowAction(button.dataset.action));
  });
  bar.addEventListener('dblclick', (event) => {
    if (!event.target.closest('button')) window.deepseekDesktop?.windowAction('maximize');
  });

  // ---------- 更新状态 ----------
  const renderUpdateStatus = (status = {}) => {
    updatePill.dataset.state = status.state || 'idle';
    if (status.state === 'downloading') updatePill.textContent = `更新 ${status.percent || 0}%`;
    else if (status.state === 'ready') updatePill.textContent = '重启更新';
    else if (status.state === 'checking') updatePill.textContent = '检查中…';
    else if (status.state === 'error') updatePill.textContent = '更新重试';
    else updatePill.textContent = status.message && status.state === 'current' ? '已是最新' : '检查更新';
    updatePill.title = status.message || '点击检查 GitHub 更新';
  };
  window.deepseekDesktop?.onUpdateStatus?.(renderUpdateStatus);
  window.deepseekDesktop?.getStatus?.().then(({ service, update }) => {
    if (service && service.state) setServiceStatus(service.state);
    renderUpdateStatus(update || {});
  }).catch(() => {});
  window.deepseekDesktop?.onServiceStatus?.((service) => {
    if (service && service.state) setServiceStatus(service.state);
  });

  // ---------- 初始主题 ----------
  window.deepseekDesktop?.getThemeList?.().then((list) => {
    if (Array.isArray(list) && list.length) themeList = list;
    renderThemeMenu();
  }).catch(() => {});
  window.deepseekDesktop?.getTheme?.().then((mode) => {
    if (mode) applyThemeMode(mode);
  }).catch(() => {});
})();
